<?php get_header(); ?><main id="main" class="container inner-page"><p class="eyebrow"><?php esc_html_e( 'ابحث عن معنى قريب منك', 'sada-clips' ); ?></p><h1><?php echo esc_html( sprintf( __( 'نتائج البحث عن: %s', 'sada-clips' ), get_search_query() ) ); ?></h1><?php get_search_form(); ?>
<?php if ( have_posts() ) : ?><div class="card-grid search-results-grid"><?php while ( have_posts() ) : the_post(); if ( get_post_type() === 'page' ) { ?><article class="card"><div class="card-body"><h2><a href="<?php echo esc_url( get_permalink() ); ?>"><?php echo esc_html( get_the_title() ); ?></a></h2><p><?php sada_excerpt(); ?></p></div></article><?php } else { get_template_part( 'template-parts/card', sada_card_kind() ); } endwhile; ?></div><?php the_posts_pagination(); else : ?><div class="empty-state"><p><?php esc_html_e( 'لم نجد نتائج. جرّب كلمة أخرى أو تصفّح الأقسام من القائمة.', 'sada-clips' ); ?></p></div><?php endif; ?></main><?php get_footer(); ?>
